];

export function DesktopAppShell({
  appMode,
  onAppModeChange,
  activeSettingsSection,
  onSettingsSectionChange,
  onImportHandwriting,
  onOpenPinnedFolder,
  foldersPanelRef,
}: DesktopAppShellProps) {
  const theme = useAppearance((state) => state.theme);
  const editorFontSize = useAppearance((state) => state.editorFontSize);
