    content: 53,
  });
  const [twoPaneLayout, setTwoPaneLayout] = useState<Record<string, number>>({
    nav: 29,
    content: 71,
  });

  const notesPanelRef = useRef<HTMLDivElement | null>(null);
  const middlePaneRef = useRef<HTMLDivElement | null>(null);

  const {
    handleFolderClick,
    handleToggle,
    handleNoteClick,
    handleFolderContextMenu,
    handleNoteContextMenu,
    handleEmptyAreaContextMenu,
    desktopContextMenuState,
    openDesktopContextMenu,
    closeDesktopContextMenu,
  } = useTreeInteractions({ foldersPanelRef });
  const {
    activeNavigationTab,
    customFoldersTreeData,
    moveSelectedNotesToTrashByShortcut,
    deleteSelectedNotesByShortcut,
    openFeedTab,
    openFoldersTab,
    middlePaneNotes,
    middlePaneNotePreviews,
    middlePaneTitle,
    middlePaneNoteClick,
    middlePaneNoteContextMenu,
  } = useDesktopNavigation({
    onAppModeChange,
    onOpenPinnedFolder,
    openDesktopContextMenu,
    closeDesktopContextMenu,
    handleNoteClick,
    handleNoteContextMenu,
  });
  const {
    activeId,
    edgeSnap,
    handleDragStart,
    handleDragMove,
    handleDragOver,
    handleDragEnd,
    handleDragCancel,
  } = useDragDrop();

  const { handleNotesKeyDown, handleFoldersKeyDown, lastLeftPaneFocusRef } =
    useKeyboardNavigation({
      appMode,
      sidebarCollapsed,
      setSidebarCollapsed,
      moveSelectedNotesToTrash: moveSelectedNotesToTrashByShortcut,
