import { APP_EXTENSIONS } from "@/features/extensions/registry";
import {
  DESIGN_FONT_OPTIONS,
  useAppearance,
} from "@/app/state/appearance-store";
import { useHandwriting } from "@/features/handwriting/hooks/handwriting-context";
import { useNotesTree } from "@/features/notes/navigation/state/notes-tree-context";
import { useRecordings } from "@/features/recording/hooks/recordings-context";
import { useSecurity } from "@/features/security/hooks/security-context";
import { useGitSync } from "@/features/sync/hooks/git-sync-context";
import { formatLastSuccessfulSync } from "@/features/sync/lib/sync-metadata";
import type { SettingsSectionId } from "@/features/settings/lib/sections";
import { DesktopContextMenu } from "./desktop-context-menu";
import { useDesktopNavigation } from "./hooks/use-desktop-navigation";
import { FoldersPanel } from "@/features/notes/navigation/ui/folders-panel";
import { FeedPanel } from "@/features/notes/navigation/ui/feed-panel";
import { useDragDrop } from "@/features/notes/navigation/hooks/use-drag-drop";
import { useKeyboardNavigation } from "@/features/notes/navigation/hooks/use-keyboard-navigation";
import { ARCHIEVE_FOLDER_PATH } from "@typenotes/shared/constants";
import { indentationWidth } from "@/shared/constants";
import { focusNoScroll } from "@/shared/lib/dom";
import type { AppMode } from "@typenotes/shared/types";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/shared/ui/tabs";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/shared/ui/popover";
import type { FeedNoteFilter } from "@/features/notes/navigation/model/feed-tree-model";
import { AppSidebar } from "./app-sidebar";
import { DesktopMiddlePane } from "./middle-pane";
import { DesktopRightPane } from "./right-pane";
import { DesktopShell } from "./desktop-shell";

type DesktopAppShellProps = {
  appMode: AppMode;
  onAppModeChange: Dispatch<SetStateAction<AppMode>>;
  activeSettingsSection: SettingsSectionId;
  onSettingsSectionChange: (section: SettingsSectionId) => void;
  onImportHandwriting: () => void;
  onOpenPinnedFolder: (path: string) => void;
  foldersPanelRef: RefObject<HTMLDivElement | null>;
};

const FEED_FILTER_OPTIONS: Array<{ value: FeedNoteFilter; label: string }> = [
  { value: "all", label: "All notes" },
  { value: "active", label: "Active" },
  { value: "reviewed", label: "Reviewed" },
  { value: "unreviewed", label: "Unreviewed" },
  { value: "archived", label: "Archived" },
];

export function DesktopAppShell({
  appMode,
  onAppModeChange,
  activeSettingsSection,
  onSettingsSectionChange,
  onImportHandwriting,
  onOpenPinnedFolder,
  foldersPanelRef,
}: DesktopAppShellProps) {
  const theme = useAppearance((state) => state.theme);
  const editorFontSize = useAppearance((state) => state.editorFontSize);
  const designFont = useAppearance((state) => state.designFont);
  const designPalettes = useAppearance((state) => state.designPalettes);
  const {
    recordingSupported,
    isRecordingAudio,
    isRecordingFinalizing,
    startRecording,
    stopRecording,
  } = useRecordings();
  const { handwritingImportBusy } = useHandwriting();
  const {
    lastSuccessfulSyncAt,
    localSyncServerStatus,
    localSyncServerBusy,
    toggleLocalSyncServer,
  } = useGitSync();
  const { lockSecurity } = useSecurity();
  const lockAppNow = useCallback(async () => {
    if (!APP_EXTENSIONS.security) {
      return;
    }
    await lockSecurity();
  }, [lockSecurity]);
  const {
    selectedFolders,
    activeFolder,
    selectedNotes,
    setSelectedFolders,
    setLastSelectedFolder,
    setSelectedNotes,
    setLastSelectedNote,
    setActiveNote,
  } = useSelection(
    useShallow((state) => ({
      selectedFolders: state.selectedFolders,
      activeFolder: state.activeFolder,
      selectedNotes: state.selectedNotes,
      setSelectedFolders: state.setSelectedFolders,
      setLastSelectedFolder: state.setLastSelectedFolder,
      setSelectedNotes: state.setSelectedNotes,
      setLastSelectedNote: state.setLastSelectedNote,
      setActiveNote: state.setActiveNote,
    }))
  );
  const {
    expanded,
    allNotePreviews,
    renamingFolder,
    renameValue,
    setRenameValue,
    submitRenameFolder,
    cancelRenameFolder,
    createNewNote,
    shouldNestNotesInNavigation,
    feedNoteFilter,
    setFeedNoteFilter,
    refreshTree,
  } = useNotesTree();

  const [sidebarCollapsed, setSidebarCollapsed] = useState(false);
  const [treeRefreshing, setTreeRefreshing] = useState(false);
  const handleRefreshClick = useCallback(() => {
    setTreeRefreshing(true);
    void refreshTree().finally(() => setTreeRefreshing(false));
  }, [refreshTree]);
  const [feedFilterOpen, setFeedFilterOpen] = useState(false);
  const [threePaneLayout, setThreePaneLayout] = useState<Record<string, number>>({
    nav: 22,
    middle: 25,
    content: 53,
  });
  const [twoPaneLayout, setTwoPaneLayout] = useState<Record<string, number>>({
    nav: 29,
    content: 71,
  });

  const notesPanelRef = useRef<HTMLDivElement | null>(null);
  const middlePaneRef = useRef<HTMLDivElement | null>(null);

  const {
    handleFolderClick,
    handleToggle,
    handleNoteClick,
    handleFolderContextMenu,
    handleNoteContextMenu,
    handleEmptyAreaContextMenu,
    desktopContextMenuState,
    openDesktopContextMenu,
    closeDesktopContextMenu,
  } = useTreeInteractions({ foldersPanelRef });
  const {
    activeNavigationTab,
    customFoldersTreeData,
    moveSelectedNotesToTrashByShortcut,
    deleteSelectedNotesByShortcut,
    openFeedTab,
    openFoldersTab,
    middlePaneNotes,
    middlePaneNotePreviews,
    middlePaneTitle,
    middlePaneNoteClick,
    middlePaneNoteContextMenu,
  } = useDesktopNavigation({
    onAppModeChange,
    onOpenPinnedFolder,
    openDesktopContextMenu,
    closeDesktopContextMenu,
    handleNoteClick,
    handleNoteContextMenu,
  });
  const {
    activeId,
    edgeSnap,
    handleDragStart,
    handleDragMove,
    handleDragOver,
    handleDragEnd,
    handleDragCancel,
  } = useDragDrop();

  const { handleNotesKeyDown, handleFoldersKeyDown, lastLeftPaneFocusRef } =
    useKeyboardNavigation({
      appMode,
      sidebarCollapsed,
      setSidebarCollapsed,
      moveSelectedNotesToTrash: moveSelectedNotesToTrashByShortcut,
      deleteSelectedNotes: deleteSelectedNotesByShortcut,
      // The lock shortcut is optional. When security is disabled, keep the
      // command surface stable but make it a no-op.
      lockAppNow,
      activeNavigationTab,
      openFeedTab,
      openFoldersTab,
      notes: middlePaneNotes,
      foldersPanelRef,
      middlePaneRef,
      notesPanelRef,
    });

  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } })
  );
  const appStyle = useMemo(
    () => {
      const fontFamily =
        DESIGN_FONT_OPTIONS.find((option) => option.id === designFont)?.family ??
        DESIGN_FONT_OPTIONS[0].family;
      return {
        "--editor-font-size": `${editorFontSize}px`,
        "--design-font": fontFamily,
        "--design-light-bg": designPalettes.light.background,
        "--design-light-text": designPalettes.light.text,
        "--design-light-muted": designPalettes.light.muted,
        "--design-light-border": designPalettes.light.border,
        "--design-light-selection": designPalettes.light.selection,
        "--design-dark-bg": designPalettes.dark.background,
        "--design-dark-text": designPalettes.dark.text,
        "--design-dark-muted": designPalettes.dark.muted,
        "--design-dark-border": designPalettes.dark.border,
        "--design-dark-selection": designPalettes.dark.selection,
      } as CSSProperties;
import type { CSSProperties, Dispatch, ReactNode, SetStateAction } from "react";
import { ResizableHandle, ResizablePanel, ResizablePanelGroup } from "@/shared/ui/resizable";

type DesktopShellProps = {
  theme: "light" | "dark";
  appStyle: CSSProperties;
  sidebarCollapsed: boolean;
  onToggleSidebar: () => void;
  showMiddlePane: boolean;
  twoPaneLayout: Record<string, number>;
  setTwoPaneLayout: Dispatch<SetStateAction<Record<string, number>>>;
  threePaneLayout: Record<string, number>;
  setThreePaneLayout: Dispatch<SetStateAction<Record<string, number>>>;
  leftPane: ReactNode;
  middlePane: ReactNode;
  rightPane: ReactNode;
};

export function DesktopShell({
  theme,
  appStyle,
  sidebarCollapsed,
  onToggleSidebar,
  showMiddlePane,
  twoPaneLayout,
  setTwoPaneLayout,
  threePaneLayout,
  setThreePaneLayout,
  leftPane,
  middlePane,
  rightPane,
}: DesktopShellProps) {
  const rightPaneWithSidebarToggle = (
    <div className="desktop-right-pane-slot">
      {rightPane}
      <button
        type="button"
        className="sidebar-toggle-btn"
        aria-label={sidebarCollapsed ? "Show sidebar" : "Hide sidebar"}
        aria-pressed={!sidebarCollapsed}
        title={sidebarCollapsed ? "Show sidebar" : "Hide sidebar"}
        onClick={onToggleSidebar}
      >
        <svg viewBox="0 0 16 16" aria-hidden>
          <rect
            x="1.25"
            y="1.75"
            width="13.5"
            height="12.5"
            rx="3.25"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.25"
          />
          <path
            d="M5.8 2.9v10.2"
            fill="none"
            stroke="currentColor"
            strokeWidth="1.25"
          />
        </svg>
      </button>
    </div>
  );

  return (
    <div className={`app theme-${theme}${sidebarCollapsed ? " sidebar-collapsed" : ""}`} style={appStyle}>
      {sidebarCollapsed ? (
        <div className="app-single-pane">{rightPaneWithSidebarToggle}</div>
      ) : !showMiddlePane ? (
        <ResizablePanelGroup
          orientation="horizontal"
          className="app-panels"
          defaultLayout={twoPaneLayout}
          onLayoutChanged={(layout) => setTwoPaneLayout(layout)}
        >
          <ResizablePanel
            id="nav"
            defaultSize="29%"
            minSize="18%"
            maxSize="44%"
            className="min-w-0 h-full min-h-0"
          >
            {leftPane}
          </ResizablePanel>
          <ResizableHandle className="app-resize-handle" />
          <ResizablePanel
            id="content"
            defaultSize="71%"
            minSize="35%"
            className="min-w-0 h-full min-h-0"
          >
            {rightPaneWithSidebarToggle}
          </ResizablePanel>
        </ResizablePanelGroup>
      ) : (
        <ResizablePanelGroup
          orientation="horizontal"
          className="app-panels"
          defaultLayout={threePaneLayout}
          onLayoutChanged={(layout) => setThreePaneLayout(layout)}
        >
          <ResizablePanel
            id="nav"
            defaultSize="22%"
            minSize="16%"
            maxSize="34%"
            className="min-w-0 h-full min-h-0"
          >
            {leftPane}
          </ResizablePanel>
          <ResizableHandle className="app-resize-handle" />
          <ResizablePanel
            id="middle"
            defaultSize="25%"
            minSize="18%"
            maxSize="40%"
            className="min-w-0 h-full min-h-0"
          >
            {middlePane}
          </ResizablePanel>
          <ResizableHandle className="app-resize-handle app-resize-handle-editor" />
          <ResizablePanel
            id="content"
            defaultSize="53%"
            minSize="30%"
            className="min-w-0 h-full min-h-0"
          >
            {rightPaneWithSidebarToggle}
          </ResizablePanel>
